import os
import json
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _span_to_dict(span: Any) -> Dict[str, Any]:
    return {
        "offset": getattr(span, "offset", None),
        "length": getattr(span, "length", None),
    }


def _polygon_to_list(polygon: Any) -> Optional[List[Dict[str, float]]]:
    if not polygon:
        return None
    pts = []
    for p in polygon:
        if isinstance(p, dict):
            x = p.get("x")
            y = p.get("y")
        else:
            x = getattr(p, "x", None)
            y = getattr(p, "y", None)
        pts.append({"x": x, "y": y})
    return pts


def _page_to_dict(page: Any) -> Dict[str, Any]:
    lines = []
    for line in getattr(page, "lines", []) or []:
        words = []
        for word in getattr(line, "words", []) or []:
            words.append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "span": _span_to_dict(getattr(word, "span", None)),
                }
            )
        lines.append(
            {
                "content": getattr(line, "content", None),
                "polygon": _polygon_to_list(getattr(line, "polygon", None)),
                "spans": [_span_to_dict(s) for s in (getattr(line, "spans", []) or [])],
                "words": words,
            }
        )

    tables = []
    for table in getattr(page, "tables", []) or []:
        cells = []
        for cell in getattr(table, "cells", []) or []:
            cells.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None),
                    "kind": getattr(cell, "kind", None),
                    "bounding_regions": [
                        {
                            "page_number": getattr(br, "page_number", None),
                            "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                        }
                        for br in (getattr(cell, "bounding_regions", []) or [])
                    ],
                    "spans": [_span_to_dict(s) for s in (getattr(cell, "spans", []) or [])],
                }
            )
        tables.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                    }
                    for br in (getattr(table, "bounding_regions", []) or [])
                ],
                "spans": [_span_to_dict(s) for s in (getattr(table, "spans", []) or [])],
                "cells": cells,
            }
        )

    return {
        "page_number": getattr(page, "page_number", None),
        "width": getattr(page, "width", None),
        "height": getattr(page, "height", None),
        "unit": getattr(page, "unit", None),
        "angle": getattr(page, "angle", None),
        "lines": lines,
        "tables": tables,
    }


def extract_layout_elements(
    document_path: str,
    *,
    model_id: str = "prebuilt-layout",
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)

    result = poller.result()

    pages = [_page_to_dict(page) for page in (getattr(result, "pages", []) or [])]

    paragraphs = []
    for para in getattr(result, "paragraphs", []) or []:
        paragraphs.append(
            {
                "content": getattr(para, "content", None),
                "role": getattr(para, "role", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                    }
                    for br in (getattr(para, "bounding_regions", []) or [])
                ],
                "spans": [_span_to_dict(s) for s in (getattr(para, "spans", []) or [])],
            }
        )

    figures = []
    for fig in getattr(result, "figures", []) or []:
        figures.append(
            {
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                    }
                    for br in (getattr(fig, "bounding_regions", []) or [])
                ],
                "spans": [_span_to_dict(s) for s in (getattr(fig, "spans", []) or [])],
            }
        )

    return {
        "content": getattr(result, "content", None),
        "pages": pages,
        "paragraphs": paragraphs,
        "tables": [table for page in pages for table in page.get("tables", [])],
        "figures": figures,
        "raw_json": json.loads(result.to_json()) if hasattr(result, "to_json") else None,
    }
